insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2af9880c-c9a9-4bf9-aa23-86ba12207100', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Divisibility and gcd', 'This module establishes divisibility and gcd as the course''s first working framework. It supplies the language and representations needed before the path advances to prime numbers.', 0),
  ('a73f96a7-8675-40f7-bf72-bf5d1541e9b0', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '2af9880c-c9a9-4bf9-aa23-86ba12207100', 'subtopic'::public.curated_course_node_type, 'Euclidean algorithm', 'Euclidean algorithm is an executable part of divisibility and gcd; its correctness, cost, and failure modes recur in later problems and implementations. It appears before bézout identity because that next topic assumes this starting point.', 0),
  ('7cdc8255-0c44-46cb-8354-cf1bd16330fc', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '2af9880c-c9a9-4bf9-aa23-86ba12207100', 'subtopic'::public.curated_course_node_type, 'Bézout identity', 'Bézout identity provides a formal guarantee or inference rule for divisibility and gcd, allowing later conclusions to be justified rather than inferred from examples alone. After euclidean algorithm, bézout identity supplies what is needed to address linear diophantine equations.', 1),
  ('b1edd6dc-8955-43b1-8ea6-2ffa59385ee9', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '2af9880c-c9a9-4bf9-aa23-86ba12207100', 'subtopic'::public.curated_course_node_type, 'Linear Diophantine equations', 'Linear Diophantine equations identifies a specific object, distinction, or relationship within divisibility and gcd. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, linear diophantine equations carries the completed idea into prime numbers.', 2),
  ('846193d8-0790-4dbc-bdbd-deb49d164853', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Prime numbers', 'This module builds directly on divisibility and gcd and develops prime numbers. It belongs here because its methods and distinctions are prerequisites for congruences.', 1),
  ('77be5c65-ccfc-4220-9a11-38073eb7691a', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '846193d8-0790-4dbc-bdbd-deb49d164853', 'subtopic'::public.curated_course_node_type, 'Fundamental theorem', 'Fundamental theorem provides a formal guarantee or inference rule for prime numbers, allowing later conclusions to be justified rather than inferred from examples alone. It appears before infinitude because that next topic assumes this starting point.', 0),
  ('c8e4a442-f743-424f-ae04-402a74a2e81d', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '846193d8-0790-4dbc-bdbd-deb49d164853', 'subtopic'::public.curated_course_node_type, 'Infinitude', 'Infinitude identifies a specific object, distinction, or relationship within prime numbers. Learners need to recognize and use it before combining this module''s ideas in later work. After fundamental theorem, infinitude supplies what is needed to address valuation.', 1),
  ('7c18e56e-0357-4b54-8567-eaa423ff03ac', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '846193d8-0790-4dbc-bdbd-deb49d164853', 'subtopic'::public.curated_course_node_type, 'Valuation', 'Valuation identifies a specific object, distinction, or relationship within prime numbers. Learners need to recognize and use it before combining this module''s ideas in later work. After infinitude, valuation supplies what is needed to address distribution questions.', 2),
  ('441fe759-1cc8-49f8-8d67-6aa2328804f5', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '846193d8-0790-4dbc-bdbd-deb49d164853', 'subtopic'::public.curated_course_node_type, 'Distribution questions', 'Distribution questions gives prime numbers a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, distribution questions carries the completed idea into congruences.', 3),
  ('e2e35a60-ef71-4bfb-8d84-ac499c075b85', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Congruences', 'This module builds directly on prime numbers and develops congruences. It belongs here because its methods and distinctions are prerequisites for chinese remainder theorem.', 2),
  ('834b4168-f33b-404a-b40d-9976f7feb331', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e2e35a60-ef71-4bfb-8d84-ac499c075b85', 'subtopic'::public.curated_course_node_type, 'Residue classes', 'Residue classes identifies a specific object, distinction, or relationship within congruences. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before inverses because that next topic assumes this starting point.', 0),
  ('8245df49-3a9f-4ef9-ad88-a15a639aaa19', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e2e35a60-ef71-4bfb-8d84-ac499c075b85', 'subtopic'::public.curated_course_node_type, 'Inverses', 'Inverses identifies a specific object, distinction, or relationship within congruences. Learners need to recognize and use it before combining this module''s ideas in later work. After residue classes, inverses supplies what is needed to address linear congruences.', 1),
  ('7a619cbc-a13e-4cb0-9022-d76229ad98ee', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e2e35a60-ef71-4bfb-8d84-ac499c075b85', 'subtopic'::public.curated_course_node_type, 'Linear congruences', 'Linear congruences identifies a specific object, distinction, or relationship within congruences. Learners need to recognize and use it before combining this module''s ideas in later work. After inverses, linear congruences supplies what is needed to address modular exponentiation.', 2),
  ('82249092-f505-4c68-81d9-8593ad9a9c36', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e2e35a60-ef71-4bfb-8d84-ac499c075b85', 'subtopic'::public.curated_course_node_type, 'Modular exponentiation', 'Modular exponentiation identifies a specific object, distinction, or relationship within congruences. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, modular exponentiation carries the completed idea into chinese remainder theorem.', 3),
  ('32087eb5-860b-47fd-8973-4263f87ea99c', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Chinese remainder theorem', 'This module builds directly on congruences and develops chinese remainder theorem. It belongs here because its methods and distinctions are prerequisites for fermat, euler, and orders.', 3),
  ('e2eadd7e-b718-4cb3-8209-9515e45abb14', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '32087eb5-860b-47fd-8973-4263f87ea99c', 'subtopic'::public.curated_course_node_type, 'Constructive solutions', 'Constructive solutions identifies a specific object, distinction, or relationship within chinese remainder theorem. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before simultaneous congruences because that next topic assumes this starting point.', 0),
  ('97e654a4-9513-4ced-bc43-92451441497e', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '32087eb5-860b-47fd-8973-4263f87ea99c', 'subtopic'::public.curated_course_node_type, 'Simultaneous congruences', 'Simultaneous congruences identifies a specific object, distinction, or relationship within chinese remainder theorem. Learners need to recognize and use it before combining this module''s ideas in later work. After constructive solutions, simultaneous congruences supplies what is needed to address applications.', 1),
  ('6b6d76f0-c03d-4bd0-8c92-c5e11de49302', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '32087eb5-860b-47fd-8973-4263f87ea99c', 'subtopic'::public.curated_course_node_type, 'Applications', 'Applications identifies a specific object, distinction, or relationship within chinese remainder theorem. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, applications carries the completed idea into fermat, euler, and orders.', 2),
  ('e04bcb26-a66f-4242-ab4e-68a117bbfe2d', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Fermat, Euler, and orders', 'This module builds directly on chinese remainder theorem and develops fermat, euler, and orders. It belongs here because its methods and distinctions are prerequisites for polynomial congruences.', 4),
  ('df39dfd4-75f3-4da9-bcd9-ca3dca45e166', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e04bcb26-a66f-4242-ab4e-68a117bbfe2d', 'subtopic'::public.curated_course_node_type, 'Phi function', 'Phi function identifies a specific object, distinction, or relationship within fermat, euler, and orders. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before groups mod n because that next topic assumes this starting point.', 0),
  ('0461a6fd-e015-49cc-8053-ef432afe5497', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e04bcb26-a66f-4242-ab4e-68a117bbfe2d', 'subtopic'::public.curated_course_node_type, 'Groups mod n', 'Groups mod n identifies a specific object, distinction, or relationship within fermat, euler, and orders. Learners need to recognize and use it before combining this module''s ideas in later work. After phi function, groups mod n supplies what is needed to address primitive roots.', 1),
  ('10fa0e78-fb80-428b-99f4-6d331d40521c', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'e04bcb26-a66f-4242-ab4e-68a117bbfe2d', 'subtopic'::public.curated_course_node_type, 'Primitive roots', 'Primitive roots identifies a specific object, distinction, or relationship within fermat, euler, and orders. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, primitive roots carries the completed idea into polynomial congruences.', 2),
  ('9b161b1e-fe78-4b35-8482-30d298735499', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Polynomial congruences', 'This module builds directly on fermat, euler, and orders and develops polynomial congruences. It belongs here because its methods and distinctions are prerequisites for quadratic residues.', 5),
  ('437701fa-1edc-438e-9233-570723f06c68', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '9b161b1e-fe78-4b35-8482-30d298735499', 'subtopic'::public.curated_course_node_type, 'Roots mod primes', 'Roots mod primes identifies a specific object, distinction, or relationship within polynomial congruences. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before hensel-lifting intuition because that next topic assumes this starting point.', 0),
  ('4699c99e-c817-4135-918c-f80407a8d23f', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '9b161b1e-fe78-4b35-8482-30d298735499', 'subtopic'::public.curated_course_node_type, 'Hensel-lifting intuition', 'Hensel-lifting intuition identifies a specific object, distinction, or relationship within polynomial congruences. Learners need to recognize and use it before combining this module''s ideas in later work. After roots mod primes, hensel-lifting intuition supplies what is needed to address finite fields preview.', 1),
  ('9d77c7e6-1e15-49fa-bfd3-864cdb94786b', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '9b161b1e-fe78-4b35-8482-30d298735499', 'subtopic'::public.curated_course_node_type, 'Finite fields preview', 'Finite fields preview identifies a specific object, distinction, or relationship within polynomial congruences. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, finite fields preview carries the completed idea into quadratic residues.', 2),
  ('c0ea35c5-5a38-40cc-a1c7-d158e8885184', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Quadratic residues', 'This module builds directly on polynomial congruences and develops quadratic residues. It belongs here because its methods and distinctions are prerequisites for diophantine equations.', 6),
  ('8a9b2474-b41f-407a-ba5e-b27fd023be94', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'c0ea35c5-5a38-40cc-a1c7-d158e8885184', 'subtopic'::public.curated_course_node_type, 'Legendre symbol', 'Legendre symbol identifies a specific object, distinction, or relationship within quadratic residues. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before euler criterion because that next topic assumes this starting point.', 0),
  ('aa75d808-7c88-4035-8118-d3ff2360cbad', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'c0ea35c5-5a38-40cc-a1c7-d158e8885184', 'subtopic'::public.curated_course_node_type, 'Euler criterion', 'Euler criterion identifies a specific object, distinction, or relationship within quadratic residues. Learners need to recognize and use it before combining this module''s ideas in later work. After legendre symbol, euler criterion supplies what is needed to address quadratic reciprocity.', 1),
  ('17403d1f-9533-4833-9cd0-e057dd065551', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', 'c0ea35c5-5a38-40cc-a1c7-d158e8885184', 'subtopic'::public.curated_course_node_type, 'Quadratic reciprocity', 'Quadratic reciprocity identifies a specific object, distinction, or relationship within quadratic residues. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, quadratic reciprocity carries the completed idea into diophantine equations.', 2),
  ('5af470c7-e7be-4e14-9aeb-b17af440cf07', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Diophantine equations', 'This module builds directly on quadratic residues and develops diophantine equations. It belongs here because its methods and distinctions are prerequisites for continued fractions.', 7),
  ('09e2351d-76ab-40d1-b889-5bca867a4d80', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '5af470c7-e7be-4e14-9aeb-b17af440cf07', 'subtopic'::public.curated_course_node_type, 'Pythagorean triples', 'Pythagorean triples identifies a specific object, distinction, or relationship within diophantine equations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before sums of squares because that next topic assumes this starting point.', 0),
  ('d75abeff-a8fe-4412-91bc-69af016575f1', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '5af470c7-e7be-4e14-9aeb-b17af440cf07', 'subtopic'::public.curated_course_node_type, 'Sums of squares', 'Sums of squares identifies a specific object, distinction, or relationship within diophantine equations. Learners need to recognize and use it before combining this module''s ideas in later work. After pythagorean triples, sums of squares supplies what is needed to address infinite descent.', 1),
  ('d95fbde7-874c-4d03-a17a-e7fef9877943', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '5af470c7-e7be-4e14-9aeb-b17af440cf07', 'subtopic'::public.curated_course_node_type, 'Infinite descent', 'Infinite descent identifies a specific object, distinction, or relationship within diophantine equations. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, infinite descent carries the completed idea into continued fractions.', 2),
  ('5db4fae4-7ee3-4389-a183-e50087d69117', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Continued fractions', 'This module builds directly on diophantine equations and develops continued fractions. It belongs here because its methods and distinctions are prerequisites for arithmetic functions.', 8),
  ('867990b1-9074-4e02-8d54-33c445bfae4a', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '5db4fae4-7ee3-4389-a183-e50087d69117', 'subtopic'::public.curated_course_node_type, 'Approximation', 'Approximation makes difficult behavior in continued fractions tractable while exposing the assumptions and accuracy limits used by later methods. It appears before convergents because that next topic assumes this starting point.', 0),
  ('fbae07ce-e7e9-401a-8a4b-c0fa4ccc2e00', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '5db4fae4-7ee3-4389-a183-e50087d69117', 'subtopic'::public.curated_course_node_type, 'Convergents', 'Convergents identifies a specific object, distinction, or relationship within continued fractions. Learners need to recognize and use it before combining this module''s ideas in later work. After approximation, convergents supplies what is needed to address pell equations.', 1),
  ('8298c496-3802-4859-8386-1daa18ae4703', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '5db4fae4-7ee3-4389-a183-e50087d69117', 'subtopic'::public.curated_course_node_type, 'Pell equations', 'Pell equations identifies a specific object, distinction, or relationship within continued fractions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, pell equations carries the completed idea into arithmetic functions.', 2),
  ('2db6c2e3-4058-4342-8906-444a95562c2b', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Arithmetic functions', 'This module builds directly on continued fractions and develops arithmetic functions. It belongs here because its methods and distinctions are prerequisites for primality and factorization.', 9),
  ('3e047cb8-a3a9-4fdd-ada6-d47cc60c2446', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '2db6c2e3-4058-4342-8906-444a95562c2b', 'subtopic'::public.curated_course_node_type, 'Möbius inversion', 'Möbius inversion identifies a specific object, distinction, or relationship within arithmetic functions. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before divisor sums because that next topic assumes this starting point.', 0);
