values
  ('5ed5c024-a78a-4f46-a24f-b83991657350', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '2db6c2e3-4058-4342-8906-444a95562c2b', 'subtopic'::public.curated_course_node_type, 'Divisor sums', 'Divisor sums identifies a specific object, distinction, or relationship within arithmetic functions. Learners need to recognize and use it before combining this module''s ideas in later work. After möbius inversion, divisor sums supplies what is needed to address average-order ideas.', 1),
  ('36bd7b64-40d0-410d-a653-7aa262916014', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '2db6c2e3-4058-4342-8906-444a95562c2b', 'subtopic'::public.curated_course_node_type, 'Average-order ideas', 'Average-order ideas identifies a specific object, distinction, or relationship within arithmetic functions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, average-order ideas carries the completed idea into primality and factorization.', 2),
  ('18ef37ea-432a-4314-9676-670a28aedad3', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Primality and factorization', 'This module builds directly on arithmetic functions and develops primality and factorization. It belongs here because its methods and distinctions are prerequisites for cryptographic number theory.', 10),
  ('53fb50f4-6548-4e37-bbac-52753739e30b', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '18ef37ea-432a-4314-9676-670a28aedad3', 'subtopic'::public.curated_course_node_type, 'Probabilistic tests', 'Probabilistic tests identifies a specific object, distinction, or relationship within primality and factorization. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before pollard methods because that next topic assumes this starting point.', 0),
  ('773cf888-f42a-4a42-9086-91cf749693e8', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '18ef37ea-432a-4314-9676-670a28aedad3', 'subtopic'::public.curated_course_node_type, 'Pollard methods', 'Pollard methods identifies a specific object, distinction, or relationship within primality and factorization. Learners need to recognize and use it before combining this module''s ideas in later work. After probabilistic tests, pollard methods supplies what is needed to address complexity.', 1),
  ('eefdcbb6-a48c-4c19-bd7b-08722efc3ee0', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '18ef37ea-432a-4314-9676-670a28aedad3', 'subtopic'::public.curated_course_node_type, 'Complexity', 'Complexity identifies a specific object, distinction, or relationship within primality and factorization. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, complexity carries the completed idea into cryptographic number theory.', 2),
  ('93da5528-e335-49f6-9f57-21537a2f215b', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', null, 'topic'::public.curated_course_node_type, 'Cryptographic number theory', 'This culminating module draws on primality and factorization and develops cryptographic number theory. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('c69ca230-38a4-4370-8eb7-46c18d2ef34a', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '93da5528-e335-49f6-9f57-21537a2f215b', 'subtopic'::public.curated_course_node_type, 'RSA', 'RSA identifies a specific object, distinction, or relationship within cryptographic number theory. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before diffie–hellman because that next topic assumes this starting point.', 0),
  ('252f1dd6-f321-4bf5-b77a-eed67e2a1006', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '93da5528-e335-49f6-9f57-21537a2f215b', 'subtopic'::public.curated_course_node_type, 'Diffie–Hellman', 'Diffie–Hellman identifies a specific object, distinction, or relationship within cryptographic number theory. Learners need to recognize and use it before combining this module''s ideas in later work. After rsa, diffie–hellman supplies what is needed to address elliptic-curve concepts.', 1),
  ('8fc16362-eeff-43f4-bacf-be6bc75ad160', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '93da5528-e335-49f6-9f57-21537a2f215b', 'subtopic'::public.curated_course_node_type, 'Elliptic-curve concepts', 'Elliptic-curve concepts identifies a specific object, distinction, or relationship within cryptographic number theory. Learners need to recognize and use it before combining this module''s ideas in later work. After diffie–hellman, elliptic-curve concepts supplies what is needed to address attacks.', 2),
  ('454dbca4-82b4-4341-804a-ac6f35048e22', '97846d63-e4d5-4aeb-b44c-704f2f7c63da', '93da5528-e335-49f6-9f57-21537a2f215b', 'subtopic'::public.curated_course_node_type, 'Attacks', 'Attacks identifies a specific object, distinction, or relationship within cryptographic number theory. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, attacks requires ideas from the complete path to be integrated and transferred.', 3);
insert into public.learning_paths (
